import {REPO,round,today,totals,shiftDate,dayFor,nextSession,brief} from './model.js';
import {BODY_FIELDS,METHODS,ensureDay,assertUnchanged,validDate,bodyValue,bodySeries,bodySummary,bodyDays,displayUnit,fromMetric,toMetric,sameDayComposition} from './body.js';
import {GitHubStore} from './sync.js';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'–':Number(n).toLocaleString('en-GB',{maximumFractionDigits:1});
const percent=(n,t)=>t>0?Math.max(0,Math.min(100,n/t*100)):0;
const id=()=>crypto.randomUUID();
const dateLabel=(d,options={day:'numeric',month:'short'})=>new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',options);
const preference=(k,fallback)=>{try{return localStorage.getItem('cams-health-'+k)||fallback;}catch{return fallback;}};
const persist=(k,v)=>{try{localStorage.setItem('cams-health-'+k,v);}catch{}};
const root=$('#app'),sheet=$('#sheet');
const state={date:today(),view:'dashboard',detail:null,theme:preference('theme','system'),units:preference('units','metric'),metric:'weightKg',range:30,filter:'',timerEnd:Number(preference('timer','0')),timerPaused:0};
if(!['system','dark','light'].includes(state.theme))state.theme='system';
if(!['metric','imperial'].includes(state.units))state.units='metric';
const paths={
  home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
  food:'M5 3v6a3 3 0 0 0 6 0V3M8 3v18M19 3v18M19 3c-5 2-5 9 0 9',
  train:'M3 8v8M6 5v14M6 12h12M18 5v14M21 8v8',
  body:'M12 3a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5ZM5 11l7-1 7 1M12 10v5M12 15l-4 6M12 15l4 6',
  more:'M5 12h.01M12 12h.01M19 12h.01',
  plus:'M12 5v14M5 12h14',close:'M6 6l12 12M6 18 18 6',
  right:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',arrow:'M4 12h16m-6-6 6 6-6 6',
  check:'m5 12 4 4L19 6',refresh:'M20 7a9 9 0 1 0 1 8M20 2v5h-5',
  sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10',
  moon:'M20 14A8 8 0 0 1 10 4 9 9 0 1 0 10 10Z',
  calendar:'M4 5h16v16H4ZM8 2v6M16 2v6M4 10h16',
  steps:'M9 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4M8 10l-2 5H3M8 10l5 4 3-2M8 10l4-3 4 2M11 14l-1 7M13 14l4 6',
  water:'M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Z',
  scale:'M4 5h16v16H4ZM8 9h8M12 9l2-3',
  tape:'M3 6h18v12H3ZM7 6v5M11 6v3M15 6v5M19 6v3',
  github:'M9 19c-5 2-5-2-7-2M15 22v-4a4 4 0 0 0-1-3c4 0 7-2 7-6a5 5 0 0 0-1-3 5 5 0 0 0 0-4s-2 0-4 2a13 13 0 0 0-7 0C7 2 5 2 5 2a5 5 0 0 0 0 4 5 5 0 0 0-1 3c0 4 3 6 7 6a4 4 0 0 0-1 3v4',
  lock:'M5 10h14v11H5ZM8 10V6a4 4 0 0 1 8 0v4M12 14v3',
  info:'M12 16v-5M12 7h.01M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',
  timer:'M9 2h6M12 5v2M18 5l2 2M12 13l3-3M12 6a8 8 0 1 0 0 16 8 8 0 0 0 0-16',
  history:'M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v6l4 2',
  download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
  copy:'M8 8h12v13H8ZM4 16H2V2h13v2',
  edit:'m4 20 4-1L20 7l-4-4L4 15ZM13 6l4 4',
  search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',
  eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',
  spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',
  coffee:'M4 7h12v10a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4ZM16 9h2a3 3 0 0 1 0 6h-2M7 2v2M12 2v2'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const button=(label,act,ico='',cls='btn',extra='')=>`<button type="button" class="${cls}" data-act="${act}" ${extra}>${ico?icon(ico):''}<span>${label}</span></button>`;
const iconButton=(label,act,ico,extra='')=>`<button type="button" class="iconbtn" data-act="${act}" aria-label="${label}" title="${label}" ${extra}>${icon(ico)}</button>`;
const heading=(title,action='')=>`<div class="section-head"><h2>${title}</h2>${action}</div>`;
const tag=(label,type='')=>`<span class="tag ${type}">${label}</span>`;
const empty=(ico,title,description,action='')=>`<div class="empty"><span class="empty-icon">${icon(ico)}</span><h3>${title}</h3><p>${description}</p>${action}</div>`;
const metricValue=(v,k)=>fmt(fromMetric(v,k,state.units));
const unit=k=>displayUnit(k,state.units);
const sessionSets=s=>s?.exercises?.reduce((a,e)=>a+(Number(e.sets)||0),0)||0;
const actualSets=w=>w.actualExercises?.reduce((a,e)=>a+(Number(e.sets)||0),0)||null;
const store=new GitHubStore({onchange:()=>{if(!sheet.open)render();}});

function applyTheme(){document.documentElement.dataset.theme=state.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):state.theme;document.querySelector('meta[name="theme-color"]').content=document.documentElement.dataset.theme==='dark'?'#0d1318':'#f4f5f0';}
applyTheme();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.theme==='system')applyTheme();});
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),5000);}
const navigation=[['dashboard','Today','home'],['nutrition','Food','food'],['training','Train','train'],['body','Body','body'],['settings','More','more']];
function nav(){return navigation.map(([key,title,ico])=>`<button data-view="${key}" class="nav-item ${state.view===key?'active':''}" ${state.view===key?'aria-current="page"':''}>${icon(ico)}<span>${title}</span>${key==='body'?'<i class="nav-new"></i>':''}</button>`).join('');}
function render(){
  if(!store.data){root.innerHTML=`<main class="boot"><div class="wordmark">cam<span>.</span></div><p>${store.error?esc(store.error):'Getting your latest records'}</p>${store.error?button('Try again','refresh','refresh'):'<div class="loader"></div>'}</main>`;return;}
  const d=dayFor(store.data,state.date),t=totals(d),titles={dashboard:'Today',nutrition:'Food diary',training:'Training',body:'Body',settings:'Your space',history:'History',workout:'Workout'};
  const title=state.detail?'Workout':titles[state.view]||'Today';
  root.innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="wordmark" href="#dashboard" data-home>cam<span>.</span><small>HEALTH STUDIO</small></a><div class="sidebar-label">YOUR DAILY PRACTICE</div><nav aria-label="Main navigation">${nav()}</nav><div class="sidebar-bottom">${button('History','history','history','sidebar-link')}<button class="account" data-act="connect"><span class="avatar">${esc(store.data.profile.name?.[0]||'C')}</span><span><b>${esc(store.data.profile.name||'Cam')}</b><small>${store.connected?'Browser authorized':'GitHub-backed records'}</small></span>${icon('right')}</button><div class="edition">STUDIO 02 <span>BUILT FOR YOUR EVERYDAY</span></div></div></aside><div class="app-content"><header class="topbar"><div class="top-title">${state.detail?iconButton('Back to training','training','left'):'<span class="brand-dot">c.</span>'}<strong>${title}</strong></div><div class="top-actions"><button class="sync-pill ${store.error?'warn':''}" data-act="sync-info" aria-label="GitHub connection status"><span class="status-dot ${store.reading||store.busy?'pulse':''}"></span><span>${store.error?'Saved copy':store.busy?'Saving':store.reading?'Syncing':'GitHub'}</span></button>${iconButton('Change appearance','theme',document.documentElement.dataset.theme==='dark'?'sun':'moon')}${iconButton('Refresh from GitHub','refresh','refresh',store.reading||store.busy?'disabled':'')}${button('Log','quick','plus','btn compact')}</div></header><main id="main" tabindex="-1">${store.error?`<div class="notice warning" role="status">${icon('info')}<div><b>Sync needs attention</b><p>${esc(store.error)}</p></div>${button('Details','sync-info','','textbtn')}</div>`:''}${state.detail?workoutDetails():state.view==='dashboard'?dashboard(d,t):state.view==='nutrition'?nutrition(d,t):state.view==='training'?training(d):state.view==='body'?bodyView():state.view==='history'?historyView():settingsView()}<footer class="sync-footer"><span><i class="status-dot ${store.error?'amber':''}"></i>${esc(store.status)}</span><span>${store.checkedAt?'Checked '+new Date(store.checkedAt).toLocaleTimeString('en-GB',{timeZone:store.data.profile.timezone,hour:'2-digit',minute:'2-digit'}):'No live read verified'} · Studio 02</span></footer></main></div><nav class="bottom-nav" aria-label="Mobile navigation">${nav()}</nav></div>`;
  attachHolds();updateTimer();
}
function dateControls(week=false){
  const monday=shiftDate(state.date,-((new Date(state.date+'T12:00:00Z').getUTCDay()+6)%7));
  return `<div class="date-controls"><div class="date-select">${iconButton('Previous day','prev','left')}<label class="date-input">${icon('calendar')}<span>${dateLabel(state.date,{day:'numeric',month:'long',year:'numeric'})}</span><input type="date" id="view-date" value="${state.date}" aria-label="View date"></label>${iconButton('Next day','next','right')}</div>${button('Today','today','','textbtn')}</div>${week?`<div class="week-strip">${Array.from({length:7},(_,i)=>{const date=shiftDate(monday,i),d=dayFor(store.data,date),logged=d.food.length||d.workouts.length||d.weightKg!=null;return `<button data-date="${date}" class="day ${date===state.date?'selected':''} ${date===today(store.data.profile.timezone)?'is-today':''}" aria-label="${dateLabel(date,{weekday:'long',day:'numeric',month:'long'})}" ${date===state.date?'aria-pressed="true"':'aria-pressed="false"'}><span>${dateLabel(date,{weekday:'short'})}</span><b>${Number(date.slice(-2))}</b><i class="${logged?'has-data':''}"></i></button>`;}).join('')}</div>`:''}`;
}
function intro(eyebrow,title,description,action=''){return `<div class="page-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function nutritionHero(d,t){
  const target=store.data.profile.targets,has=d.food.length>0,remain=target.kcal==null||t.missing.kcal?null:round(target.kcal-t.kcal),progress=percent(t.kcal,target.kcal);
  return `<section class="nutrition-card card"><div class="card-kicker"><span class="eyebrow">YOUR DAILY FUEL</span>${button(t.pending?'Incomplete macros':t.estimated?'Includes estimates':'Daily summary','brief','arrow','textbtn small')}</div><div class="energy-layout"><div class="energy-number"><span class="caption">Calories logged</span><div><strong>${has?fmt(t.kcal):'–'}</strong><span>kcal${t.missing.kcal?' + ?':''}</span></div><p>${has&&remain!=null?`<b>${fmt(Math.abs(remain))} kcal ${remain<0?'over target':'remaining'}</b><span>of ${fmt(target.kcal)} kcal</span>`:has?'Known subtotal. Some calories are missing.':'Your first meal starts the picture.'}</p></div><div class="energy-ring" role="img" aria-label="${has?Math.round(progress)+' percent of calorie target logged':'No food logged'}"><svg viewBox="0 0 120 120"><circle class="ring-track" cx="60" cy="60" r="51"/><circle class="ring-fill" cx="60" cy="60" r="51" pathLength="100" stroke-dasharray="${progress} 100"/></svg><div>${icon('spark')}<b>${has&&target.kcal?Math.round(progress)+'%':'–'}</b><small>OF TARGET</small></div></div></div><div class="macro-grid">${[['protein','Protein'],['carbs','Carbs'],['fat','Fat']].map(([k,name])=>`<div class="macro ${k}"><span><i></i>${name}</span><strong>${has?fmt(t[k]):'–'}<small>g${t.missing[k]?' + ?':''}</small></strong><div class="macro-meta">${target[k]!=null?'/ '+fmt(target[k])+' g target':t.missing[k]?'Known subtotal':'Logged today'}</div>${target[k]>0?`<div class="track"><i style="width:${percent(t[k],target[k])}%"></i></div>`:'<div class="track subtle"></div>'}</div>`).join('')}</div></section>`;
}
function foodIcon(f){return /coffee|latte/i.test(f.name)?'coffee':/protein|shake/i.test(f.name)?'water':'food';}
function foodRows(foods,limit=null){return `<div class="food-list">${(limit?foods.slice(0,limit):foods).map(f=>`<button class="food-row" data-food="${esc(f.id)}" data-name="${esc(f.name.toLowerCase())}"><span class="item-icon ${foodIcon(f)}">${icon(foodIcon(f))}</span><span class="row-description"><b>${esc(f.name)}</b><small>${esc(f.quantity)}${f.reviewRequired?' <i class="review-dot" title="Nutrition needs review"></i>':''}</small></span><span class="row-value"><b>${f.estimated&&f.kcal!=null?'≈ ':''}${fmt(f.kcal)}</b><small>kcal</small></span>${icon('right','chevron')}</button>`).join('')}</div>`;}
function activity(d){return `<div class="activity-grid">${[['steps','steps','Steps',d.steps,'steps'],['water','water','Water',d.waterMl==null?null:d.waterMl/1000,'L'],['body-log','scale','Weight',fromMetric(d.weightKg,'weightKg',state.units),unit('weightKg')]].map(([act,ico,name,value,u])=>`<button class="activity-card card" data-act="${act}"><span class="caption">${icon(ico)}${name}${icon('plus','tiny')}</span><strong>${fmt(value)}<small>${value!=null?u:''}</small></strong><span class="subtle-text">${value==null?'Not logged':name==='Steps'?fmt(store.data.profile.targets.steps)+' goal':'Recorded today'}</span></button>`).join('')}</div>`;}
function workoutTile(s,featured=false){return `<article class="workout-tile ${featured?'featured':''}"><button class="workout-open" data-workout="${esc(s.id)}"><div class="workout-label"><span class="eyebrow">${featured?'NEXT IN YOUR ROTATION':'YOUR PROGRAM'}</span>${icon('arrow')}</div><h3>${esc(s.name)}</h3><p>${esc(s.focus)}</p><div class="workout-chips">${tag(s.id==='rest'?'Recovery':s.exercises.length+' exercises')}${s.id!=='rest'?tag(sessionSets(s)+' prescribed sets'):''}</div></button><button class="preview" data-preview="${esc(s.id)}" aria-label="Preview ${esc(s.name)}">${icon('eye')}</button></article>`;}
function recordedWorkouts(d,date=state.date){return d.workouts.length?`<div class="record-list">${d.workouts.map(w=>`<button class="record-row" data-record="${esc(w.id)}" data-record-date="${date}"><span class="item-icon lilac">${icon(w.status==='completed'?'check':'train')}</span><span class="row-description"><b>${esc(w.name)}</b><small>${w.status==='completed'?'Completed':'Partial'}${actualSets(w)?' · '+actualSets(w)+' reported sets':''}${w.durationMin!=null?' · '+fmt(w.durationMin)+' min':''}</small></span>${icon('right')}</button>`).join('')}</div>`:'';}
function trainingNotice(){return store.data.profile.trainingStatus==='ready'?'':`<div class="notice soft">${icon('info')}<div><b>${store.data.profile.trainingStatus==='paused'?'Training paused':'Exercise clearance unconfirmed'}</b><p>Your stored plan is available to view. This app does not confirm that you are cleared to train.</p></div></div>`;}
function dashboard(d,t){
  const next=nextSession(store.data,state.date),weight=bodySummary(store.data,'weightKg',state.date).last;
  return `${intro('YOUR DAY, IN FOCUS',`Hey, ${esc(store.data.profile.name||'Cam')}<span class="accent">.</span>`,'Your effort. Your numbers. One place.')}${dateControls(true)}<div class="dashboard-grid"><div class="primary-column">${nutritionHero(d,t)}${activity(d)}<section>${heading('On the menu',button('View all','food-page','arrow','textbtn'))}<div class="card">${d.food.length?foodRows(d.food):empty('food','Nothing logged yet','Tell me in chat, or add your first meal here.',button('Add food','food-log','plus'))}<div class="card-bottom"><span>${d.food.length} food entries</span>${button('Add food','food-log','plus','textbtn')}</div></div></section></div><div class="secondary-column"><section>${heading('Your training',button('Open plan','training','arrow','textbtn'))}${recordedWorkouts(d)}${next?workoutTile(next,true):''}</section><section class="body-teaser card"><div class="card-kicker"><span class="eyebrow">BEYOND THE SCALE</span><span class="item-icon lilac">${icon('body')}</span></div><h3>A fuller picture<br> of your progress.</h3><p>Weight, body fat and tape measurements, kept together over time.</p>${weight?`<div class="teaser-reading"><strong>${metricValue(weight.value,'weightKg')}<small>${unit('weightKg')}</small></strong><span>Last reading · ${dateLabel(weight.date)}</span></div>`:''}${button('Open Body','body','arrow','btn secondary')}</section>${trainingNotice()}</div></div>`;
}
function nutrition(d,t){return `${intro('NUTRITION', 'Food, without the fuss.', 'Keep the portions. Keep the context. Let the totals follow.',button('Log food','food-log','plus'))}${dateControls()}<div class="dashboard-grid"><div class="primary-column">${nutritionHero(d,t)}<section>${heading('Your food diary',tag(d.food.length+' entries'))}<label class="search-field">${icon('search')}<input id="food-search" type="search" placeholder="Find something you logged" aria-label="Search today’s food"></label><div class="card">${d.food.length?foodRows(d.food):empty('food','A fresh page','Food you log will appear here.',button('Add food','food-log','plus'))}<p id="search-empty" class="help padded" hidden>No matching entries.</p></div></section></div><div class="secondary-column"><section>${heading('Quick repeat')}<p class="help">Review a previous portion before saving it again.</p><div class="card repeat-list">${recentFood().length?recentFood().map(f=>`<button class="record-row" data-repeat="${esc(f.id)}" data-origin="${f.date}"><span class="item-icon">${icon(foodIcon(f))}</span><span class="row-description"><b>${esc(f.name)}</b><small>${esc(f.quantity)} · ${fmt(f.kcal)} kcal</small></span>${icon('plus')}</button>`).join(''):empty('history','Build your shortcuts','Your recent foods become repeatable here.')}</div></section><section>${heading('Saved recipes')}<div class="card">${(store.data.recipes||[]).map(r=>`<button class="record-row" data-recipe="${esc(r.id)}"><span class="item-icon peach">${icon('food')}</span><span class="row-description"><b>${esc(r.name)}</b><small>${fmt(r.yieldG)} g batch · choose your portion</small></span>${icon('plus')}</button>`).join('')||empty('food','No saved recipes','Batch recipes can be added through chat.')}</div></section>${t.pending?`<div class="notice soft">${icon('info')}<div><b>Some nutrition is missing</b><p>${t.pending} ${t.pending===1?'entry has':'entries have'} unknown values. The + ? marker means the total is incomplete, not zero.</p></div></div>`:''}</div></div>`;}
function recentFood(){const seen=new Set();return Object.entries(store.data.days).filter(([d])=>d<=state.date).sort(([a],[b])=>b.localeCompare(a)).flatMap(([date,d])=>d.food.map(f=>({...f,date}))).filter(f=>{const key=f.name+'|'+f.quantity;if(seen.has(key))return false;seen.add(key);return true;}).slice(0,5);}
function training(d){return `${intro('TRAINING', 'Show up. Build back.', 'Your saved rotation, with the work you actually did.',button('Log session','workout-log','plus'))}${dateControls()}${trainingNotice()}<div class="section-head"><h2>Today’s work</h2>${button('Rest timer','timer','timer','textbtn')}</div>${d.workouts.length?recordedWorkouts(d):`<div class="card">${empty('train','No session logged','Prescribed workouts are not automatically marked as done.',button('Log a session','workout-log','plus'))}</div>`}<section>${heading('Your rotation',tag('PUSH / PULL / LEGS'))}<p class="help">Hold to preview. Tap for the details. Only completed program sessions advance the rotation.</p><div class="workout-grid">${store.data.training.rotation.map(sid=>store.data.training.sessions.find(s=>s.id===sid)).filter(Boolean).map(s=>workoutTile(s,nextSession(store.data,state.date)?.id===s.id)).join('')}</div></section><section>${heading('Recent sessions')}<div class="card">${Object.entries(store.data.days).filter(([date])=>date<=state.date).sort(([a],[b])=>b.localeCompare(a)).filter(([,d])=>d.workouts.length).slice(0,10).map(([date,day])=>`<div class="history-date">${dateLabel(date,{weekday:'short',day:'numeric',month:'short'})}</div>${recordedWorkouts(day,date)}`).join('')||empty('history','Your training story starts here','Completed and partial sessions will appear together.')}</div></section><details class="card disclosure"><summary>Program notes ${icon('plus')}</summary><div class="padded">${(Array.isArray(store.data.training.notes)?store.data.training.notes:[store.data.training.notes]).filter(Boolean).map(n=>`<p class="help">${esc(n)}</p>`).join('')}</div></details>`;}
function exerciseList(s){return `<ol class="exercise-list">${s.exercises.map((e,i)=>`<li><span class="exercise-index">${String(i+1).padStart(2,'0')}</span><div><b>${esc(e.name)}</b><span>${esc(e.sets)} sets × ${esc(e.reps)}${/sec/i.test(e.reps)?'':' reps'}</span>${e.note?`<details><summary>Technique & progression</summary><p>${esc(e.note)}</p></details>`:''}</div><button class="rest-chip" data-seconds="${Number(e.rest)||60}" aria-label="Start ${Number(e.rest)||60} second rest timer">${icon('timer')}${Number(e.rest)||60}s</button></li>`).join('')}</ol>`;}
function workoutDetails(){const s=store.data.training.sessions.find(s=>s.id===state.detail);if(!s)return empty('train','Workout not found','This session may have changed.',button('Back to training','training','left'));return `${intro('YOUR PROGRAM',esc(s.name),esc(s.focus))}${trainingNotice()}<div class="workout-detail-stats">${tag(s.exercises.length+' exercises')}${tag(sessionSets(s)+' prescribed sets')}${tag('Not a performance log')}</div><div class="card">${s.id==='rest'?empty('moon','Recovery is part of the plan','Log your rest day to advance the rotation.'):exerciseList(s)}</div><div class="detail-footer">${button(s.id==='rest'?'Log rest day':'Log this session','workout-log','check','btn',`data-session="${esc(s.id)}"`)}${button('Rest timer','timer','timer','btn secondary')}</div>`;}
function chart(points,key,{mixed=false}={}) {
  if(!points.length)return `<div class="chart-empty"><div class="chart-grid-placeholder"></div><span class="empty-icon">${icon('history')}</span><h3>Your trend starts here.</h3><p>Add a reading. No invented starting point, no pretend progress.</p>${button('Add a measurement','body-log','plus','btn secondary')}</div>`;
  const values=points.map(p=>fromMetric(p.value,key,state.units)),lo=Math.min(...values),hi=Math.max(...values),pad=Math.max((hi-lo)*.2,key==='bodyFatPct'?.5:.4),min=Math.max(0,lo-pad),max=hi+pad;
  const start=Date.parse(points[0].date),end=Date.parse(points.at(-1).date),x=p=>end===start?350:54+(Date.parse(p.date)-start)/(end-start)*616,y=v=>180-(v-min)/(max-min)*142;
  const line=points.map((p,i)=>`${i?'L':'M'}${x(p).toFixed(2)},${y(values[i]).toFixed(2)}`).join(' ');
  return `<div class="trend-chart"><svg viewBox="0 0 700 222" role="img" aria-label="${esc(key)} readings from ${points[0].date} to ${points.at(-1).date}; ${points.length} recorded values"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="currentColor" stop-opacity=".17"/><stop offset="100%" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(t=>{const yy=38+t*142;return `<path class="chart-gridline" d="M54 ${yy}H674"/><text x="42" y="${yy+4}" text-anchor="end">${fmt(max-t*(max-min))}</text>`;}).join('')}${points.length>1&&!mixed?`<path d="${line}L${x(points.at(-1))},181 L${x(points[0])},181Z" fill="url(#chart-fill)"/><path class="chart-line" d="${line}"/>`:''}${points.map((p,i)=>`<circle class="chart-point" cx="${x(p)}" cy="${y(values[i])}" r="4.5"><title>${p.date}: ${fmt(values[i])} ${unit(key)}${key==='bodyFatPct'?' · '+p.method:''}</title></circle>`).join('')}<text x="54" y="211">${dateLabel(points[0].date)}</text><text x="674" y="211" text-anchor="end">${dateLabel(points.at(-1).date)}</text></svg></div>`;
}
function bodyView(){
  const weight=bodySummary(store.data,'weightKg',state.date),fat=bodySummary(store.data,'bodyFatPct',state.date),waist=bodySummary(store.data,'waist',state.date),rows=bodyDays(store.data,state.date),points=bodySeries(store.data,state.metric,state.date,state.range),summary=bodySummary(store.data,state.metric,state.date),mixed=state.metric==='bodyFatPct'&&new Set(points.map(p=>p.method)).size>1,comp=sameDayComposition(store.data,state.date);
  const metricName=state.metric==='weightKg'?'Body weight':state.metric==='bodyFatPct'?'Body fat':BODY_FIELDS.find(([k])=>k===state.metric)?.[1];
  return `${intro('BODY / COMPOSITION','The bigger picture.','A dated record of your body. Not just a number on the scale.',button('Check in','body-log','plus'))}${dateControls()}<div class="body-summary-grid">${[['weightKg','Body weight',weight,'scale'],['bodyFatPct','Body fat',fat,'body'],['waist','Waist',waist,'tape']].map(([key,label,s,ico])=>`<button class="body-stat card ${key==='weightKg'?'primary-stat':''}" data-metric="${key}"><div class="caption">${icon(ico)}${label}${icon('arrow','tiny')}</div><strong>${metricValue(s.last?.value??null,key)}<small>${unit(key)}</small></strong><div class="stat-baseline">${s.last?'Last reading · '+dateLabel(s.last.date):'No reading yet'}</div>${s.change!=null&&(key!=='bodyFatPct'||s.first.method===s.last.method)?`<span class="delta">${s.change>0?'+':''}${metricValue(s.change,key)} ${key==='bodyFatPct'?'percentage points':unit(key)} <span>since ${dateLabel(s.first.date)}</span></span>`:'<span class="delta muted">'+(key==='bodyFatPct'&&s.count>1?'Methods differ; compare with care':'Your baseline builds from real readings')+'</span>'}</button>`).join('')}</div><div class="body-layout"><div class="primary-column"><section class="card trend-card"><div class="card-kicker"><div><span class="eyebrow">PROGRESS OVER TIME</span><h2>${esc(metricName)}</h2></div><label class="select-wrap"><select id="metric-select" aria-label="Choose chart metric">${[['weightKg','Body weight'],['bodyFatPct','Body fat'],...BODY_FIELDS].map(([k,l])=>`<option value="${k}" ${k===state.metric?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="chart-toolbar"><span class="chart-reading">${metricValue(points.at(-1)?.value??null,state.metric)}<small>${unit(state.metric)}</small></span><div class="segmented" role="group" aria-label="Chart date range">${[7,30,90,'all'].map(r=>`<button data-range="${r}" aria-pressed="${String(state.range)===String(r)}" class="${String(state.range)===String(r)?'selected':''}">${r==='all'?'All':r+'D'}</button>`).join('')}</div></div>${chart(points,state.metric,{mixed})}<div class="chart-foot"><span>${points.length} ${points.length===1?'reading':'readings'} in this range</span><span>${state.metric==='weightKg'&&summary.weekCount?`7-day mean: ${metricValue(summary.weekMean,'weightKg')} ${unit('weightKg')} · ${summary.weekCount} readings`:'Missing days are not filled in'}</span></div>${mixed?'<p class="inline-warning">Body-fat methods differ in this range. Points are shown without a connecting trend line.</p>':''}${points.length?`<details class="chart-data"><summary>View recorded values ${icon('plus')}</summary><div class="table-scroll"><table><thead><tr><th>Date</th><th>${esc(metricName)} (${unit(state.metric)})</th>${state.metric==='bodyFatPct'?'<th>Method</th>':''}</tr></thead><tbody>${[...points].reverse().map(p=>`<tr><td>${p.date}</td><td>${metricValue(p.value,state.metric)}</td>${state.metric==='bodyFatPct'?`<td>${esc(p.method)}</td>`:''}</tr>`).join('')}</tbody></table></div></details>`:''}</section><section>${heading('Tape measurements',button('Update','body-log','plus','textbtn'))}<div class="card measurement-grid">${BODY_FIELDS.map(([k,l])=>{const last=bodySummary(store.data,k,state.date).last;return `<button data-metric="${k}" class="measurement"><span>${l}</span><b>${metricValue(last?.value??null,k)}<small>${unit(k)}</small></b><small>${last?dateLabel(last.date):'Not recorded'}</small></button>`;}).join('')}</div></section></div><div class="secondary-column"><section class="card checkin-card"><span class="eyebrow">A MOMENT TO CHECK IN</span><div class="checkin-art">${icon('body')}<span class="orbit orbit-one"></span><span class="orbit orbit-two"></span></div><h3>Your body has<br>more than one metric.</h3><p>Log only what you measured. Leave the rest blank, and add the method behind each body-fat reading.</p>${button('Log measurements','body-log','plus','btn full')}</section>${comp?`<section class="card composition"><span class="eyebrow">SAME-DAY ESTIMATE</span><h3>Body composition</h3><div><span>Fat mass</span><b>${metricValue(comp.fat,'weightKg')} ${unit('weightKg')}</b></div><div><span>Fat-free mass</span><b>${metricValue(comp.fatFree,'weightKg')} ${unit('weightKg')}</b></div><p class="help">Calculated from the weight and body-fat percentage entered for ${dateLabel(state.date)}. Fat-free mass is not the same as muscle mass.</p></section>`:''}<div class="notice soft">${icon('lock')}<div><b>Your storage, clearly labelled</b><p>This repository is public. Measurements you save to GitHub can be viewed by others. No progress photos are uploaded.</p></div></div></div></div><section>${heading('Measurement history',button('Export CSV','body-export','download','textbtn'))}<div class="card">${rows.length?rows.slice(0,30).map(([date,d])=>`<button class="record-row" data-body-date="${date}"><span class="date-square"><small>${dateLabel(date,{month:'short'})}</small><b>${Number(date.slice(-2))}</b></span><span class="row-description"><b>${d.weightKg!=null?metricValue(d.weightKg,'weightKg')+' '+unit('weightKg'):'Body check-in'}${d.body?.bodyFatPct!=null?' · '+fmt(d.body.bodyFatPct)+'% body fat':''}</b><small>${BODY_FIELDS.filter(([k])=>d.body?.measurementsCm?.[k]!=null).length} tape measurements${d.body?.method?' · '+esc(d.body.method):''}</small></span>${icon('edit')}</button>`).join(''):empty('history','No measurements recorded','Your first check-in becomes your baseline.',button('Create a baseline','body-log','plus','btn secondary'))}</div></section>`;
}
function historyView(){
 const dates=Array.from({length:7},(_,i)=>shiftDate(state.date,i-6)),all=Object.entries(store.data.days).filter(([date])=>date<=state.date).sort(([a],[b])=>b.localeCompare(a)),max=Math.max(store.data.profile.targets.kcal||1,...dates.map(date=>totals(dayFor(store.data,date)).kcal));
 return `${intro('YOUR HISTORY','One day at a time.','Recorded days, honest gaps, and the context behind your numbers.')}${dateControls()}<section class="card weekly-card"><div class="card-kicker"><h2>Last seven days</h2>${tag('LOGGED CALORIES')}</div><div class="bar-chart">${dates.map(date=>{const d=dayFor(store.data,date),t=totals(d);return `<button class="bar-column" data-date="${date}" aria-label="${date}: ${d.food.length?fmt(t.kcal)+' logged calories':'food not logged'}"><span>${d.food.length?fmt(t.kcal):'–'}</span><div class="bar-space"><i class="${date===state.date?'current':''}" style="height:${d.food.length?Math.max(2,t.kcal/max*100):0}%"></i></div><small>${dateLabel(date,{weekday:'short'})}</small></button>`;}).join('')}</div><p class="help">Bars show logged food only. A partial food log is not a full day’s intake.</p></section><section>${heading('Your daily records')}<div class="card">${all.map(([date,d])=>{const t=totals(d);return `<button class="record-row" data-date="${date}"><span class="date-square"><small>${dateLabel(date,{month:'short'})}</small><b>${Number(date.slice(-2))}</b></span><span class="row-description"><b>${dateLabel(date,{weekday:'long'})}</b><small>${d.food.length?d.food.length+' food entries':'Food not logged'} · ${d.workouts.length} sessions</small></span><span class="row-value"><b>${d.food.length?fmt(t.kcal):'–'}</b><small>kcal${t.missing.kcal?' + ?':''}</small></span>${icon('right')}</button>`;}).join('')||empty('history','No records yet','Your logs will appear here.')}</div></section>`;
}
function settingsView(){return `${intro('YOUR SPACE','Built around you.','Your preferences, your connection, your records.')}<div class="settings-layout"><section class="card connection-card"><div class="card-kicker"><span class="item-icon">${icon('github')}</span>${tag(store.connected?'TOKEN ACCEPTED':'LIVE READ ACCESS',store.connected?'green':'')}</div><h2>GitHub is your home base.</h2><p>Your records come from <b>CameronNel/Cam-s-Health</b>. Chat can save through its own connection. Browser editing needs separate authorization.</p><div class="connection-line"><span class="status-dot"></span><div><b>${store.connected?esc(store.account):'Read access works without a token'}</b><small>${store.connected?'Token held only in this tab. Write permission is checked when you save.':'Connect to save measurements, meals and sessions here.'}</small></div></div>${button(store.connected?'Manage connection':'Connect browser editing','connect','github','btn full')}<p class="help privacy-copy">Repository is public. Food, workouts and body measurements saved here are publicly accessible.</p></section><div class="primary-column"><section class="card preference-card"><span class="eyebrow">MAKE IT FEEL LIKE YOURS</span><h2>Appearance</h2><div class="theme-options">${[['system','System','spark'],['light','Light','sun'],['dark','Dark','moon']].map(([v,l,i])=>`<button data-theme="${v}" aria-pressed="${state.theme===v}" class="theme-option ${state.theme===v?'selected':''}"><div class="theme-preview ${v}"><i></i><i></i><i></i></div><span>${icon(i)}${l}${state.theme===v?icon('check'):''}</span></button>`).join('')}</div><div class="preference-row"><div><b>Measurement units</b><p>Stored in kilograms and centimetres.</p></div><div class="segmented" role="group" aria-label="Display units">${[['metric','kg / cm'],['imperial','lb / in']].map(([v,l])=>`<button data-units="${v}" aria-pressed="${state.units===v}" class="${state.units===v?'selected':''}">${l}</button>`).join('')}</div></div></section><section class="card settings-links">${[['Targets & profile','targets','edit','Daily targets and height'],['History','history','history','Review earlier days'],['Export all records','export','download','Download your current GitHub data'],['Daily brief','brief','copy','Copy or print the selected day'],['Sync diagnostics','sync-info','refresh','Source, status and the last verified save']].map(([l,a,i,sub])=>`<button class="record-row" data-act="${a}"><span class="item-icon">${icon(i)}</span><span class="row-description"><b>${l}</b><small>${sub}</small></span>${icon('right')}</button>`).join('')}</section></div></div><p class="version-note">CAM’S HEALTH / STUDIO 02<br>Static app. GitHub records. No application backend. No analytics.</p>`;}

const TOKEN_URL='https://github.com/settings/personal-access-tokens/new?name=Cam%27s%20Health&description=Browser%20editing%20for%20Cam-s-Health&target_name=CameronNel&expires_in=30&contents=write';
let returnFocus=null,dirty=false,closingFromHistory=false;
function openSheet(title,content,setup=()=>{}) {
  if(!sheet.open){returnFocus=document.activeElement;history.pushState({...history.state,sheet:true},'');}
  dirty=false;sheet.innerHTML=`<div class="sheet-grip"></div><header class="sheet-head"><h2 id="sheet-title">${title}</h2>${iconButton('Close dialog','close-sheet','close')}</header><div class="sheet-content">${content}</div><div class="discard-confirm" hidden><b>Discard unsaved changes?</b><p>These edits have not been saved to GitHub.</p><div class="form-actions">${button('Keep editing','keep-editing','','btn secondary')}${button('Discard','discard','','btn danger')}</div></div>`;
  sheet.setAttribute('aria-labelledby','sheet-title');document.body.classList.add('sheet-open');
  if(!sheet.open)sheet.showModal();sheet.scrollTop=0;setup();
}
function closeSheet(force=false) {
  if(dirty&&!force){$('.discard-confirm',sheet).hidden=false;$('.discard-confirm button',sheet).focus();return;}
  dirty=false;sheet.close();
  if(history.state?.sheet&&!closingFromHistory)history.back();
}
sheet.addEventListener('cancel',event=>{event.preventDefault();closeSheet();});
sheet.addEventListener('input',e=>{if(e.target.closest('form')&&e.target.name!=='githubToken')dirty=true;});
sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();}});
sheet.addEventListener('close',()=>{document.body.classList.remove('sheet-open');sheet.innerHTML='';render();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});else $('#main')?.focus({preventScroll:true});});
function authFields(){return store.connected?`<p class="auth-status">${icon('lock')}Save to GitHub as ${esc(store.account)}. Verified after writing.</p>`:`<details class="inline-connect"><summary>${icon('github')}Connect GitHub to save here ${icon('plus')}</summary><p>Chat’s GitHub connection is separate from this browser. Create a fine-grained token for <b>only Cam-s-Health</b> with <b>Contents: Read and write</b>.</p><a class="btn secondary full" href="${TOKEN_URL}" target="_blank" rel="noopener noreferrer">Create token on GitHub ${icon('arrow')}</a><label class="field">GitHub token<input name="githubToken" type="password" autocomplete="off" spellcheck="false" autocapitalize="off" placeholder="Paste token in this form, never in chat"></label><small>Held in memory for this tab only. Never written into your repository or browser storage.</small></details>`;}
function numberField(name,label,value,{min=0,max=100000,step='any',help='',placeholder='Not measured',wide=false}={}){return `<label class="field ${wide?'wide':''}">${label}<input name="${name}" type="number" inputmode="decimal" min="${min}" max="${max}" step="${step}" value="${value==null?'':esc(value)}" placeholder="${esc(placeholder)}">${help?`<small>${help}</small>`:''}</label>`;}
function saveFooter(label='Save to GitHub'){return `${authFields()}<p class="form-error" role="alert" id="form-error"></p><div class="form-actions sticky-actions">${button('Cancel','close-sheet','','btn secondary')}<button class="btn" type="submit">${icon('check')}<span>${label}</span></button></div>`;}
function wireForm(handler) {
  $('form',sheet).addEventListener('submit',async event=>{
    event.preventDefault();const form=event.target,fd=new FormData(form),controls=$$('input,select,textarea,button',form),error=$('#form-error',form);error.textContent='';
    if(!store.connected&&!fd.get('githubToken')?.trim()){const details=$('.inline-connect',form);if(details)details.open=true;error.textContent='Connect your GitHub token below to save. Your entries are still in this form.';$('[name=githubToken]',form)?.focus();return;}
    controls.forEach(c=>c.disabled=true);form.setAttribute('aria-busy','true');
    try {
      if(!store.connected)await store.connect(fd.get('githubToken'));
      const token=$('[name=githubToken]',form);if(token)token.value='';
      await handler(fd);dirty=false;closeSheet(true);toast('Saved and verified on GitHub.');
    }catch(e){error.textContent=e.message;error.scrollIntoView({block:'nearest'});}
    finally {controls.forEach(c=>c.disabled=false);form.removeAttribute('aria-busy');}
  });
}
function bodyForm(date=state.date){
  const baseline=structuredClone(dayFor(store.data,date)),b=baseline.body||{},display={};
  const value=(key,raw)=>{const n=fromMetric(raw,key,state.units);return display[key]=n==null?'':String(Math.round(n*100)/100);};
  const previous=k=>{const last=bodySummary(store.data,k,shiftDate(date,-1)).last;return last?`Previous: ${metricValue(last.value,k)} ${unit(k)} · ${dateLabel(last.date)}`:'';};
  openSheet('Body check-in',`<form id="body-form"><div class="form-date">${icon('calendar')}<b>${dateLabel(date,{weekday:'long',day:'numeric',month:'long'})}</b>${tag(state.units==='metric'?'kg / cm':'lb / in')}</div><p class="help">Enter readings for this date only. Blank means unknown, not zero. Existing values for this date can be corrected or cleared.</p><div class="form-grid">${numberField('weightKg',`Body weight (${unit('weightKg')})`,value('weightKg',baseline.weightKg),{min:.01,max:fromMetric(500,'weightKg',state.units),help:previous('weightKg')})}${numberField('bodyFatPct','Body fat (%)',value('bodyFatPct',b.bodyFatPct),{min:.01,max:99.9,help:previous('bodyFatPct')})}<label class="field wide">Body-fat measurement method<select name="method">${METHODS.map(m=>`<option ${m===(b.method||METHODS[0])?'selected':''}>${m}</option>`).join('')}</select></label></div><details class="measurement-fields" ${BODY_FIELDS.some(([k])=>b.measurementsCm?.[k]!=null)?'open':''}><summary>${icon('tape')}Tape measurements <span>13 optional fields</span>${icon('plus')}</summary><p class="help">Use the same landmarks and relaxed or flexed state each time. Record that context in your notes.</p><div class="form-grid">${BODY_FIELDS.map(([k,l])=>numberField(k,l+' ('+unit(k)+')',value(k,b.measurementsCm?.[k]),{min:.01,max:fromMetric(400,k,state.units),help:previous(k)})).join('')}</div></details><label class="field">Measurement notes<textarea name="notes" rows="3" maxlength="5000" placeholder="e.g. Morning, before breakfast; arms flexed">${esc(b.notes)}</textarea></label><div class="notice soft compact-notice">${icon('info')}<p>This repository is public. Saved measurements are publicly accessible.</p></div>${saveFooter('Save check-in')}</form>`,()=>wireForm(async fd=>{
    const read=(key,old)=>String(fd.get(key)??'')===display[key]?old??null:fd.get(key)===''?null:toMetric(Number(fd.get(key)),key,state.units);
    const weight=read('weightKg',baseline.weightKg),body={...b,bodyFatPct:read('bodyFatPct',b.bodyFatPct),method:fd.get('method'),measurementsCm:{...b.measurementsCm},notes:fd.get('notes').trim(),recordedAt:new Date().toISOString()};
    for(const [k] of BODY_FIELDS)body.measurementsCm[k]=read(k,b.measurementsCm?.[k]);
    if(weight==null&&body.bodyFatPct==null&&!Object.values(body.measurementsCm).some(v=>v!=null)&&!body.notes&&!baseline.body&&baseline.weightKg==null)throw Error('Enter at least one measurement or note.');
    await store.save(data=>{const day=ensureDay(data,date);assertUnchanged(day.weightKg,baseline.weightKg);assertUnchanged(day.body,baseline.body);day.weightKg=weight;day.body=body;},`Update body check-in for ${date}`);
  }));
}
function foodDetails(foodId){const f=dayFor(store.data,state.date).food.find(f=>f.id===foodId);if(!f)return;openSheet('Food details',`<div class="food-detail-top"><span class="item-icon large">${icon(foodIcon(f))}</span><h3>${esc(f.name)}</h3><p>${esc(f.quantity)}</p><strong>${fmt(f.kcal)}<small> kcal</small></strong>${tag(f.estimated?'Estimated nutrition':'Recorded nutrition')}</div><div class="detail-macros">${[['protein','Protein'],['carbs','Carbs'],['fat','Fat']].map(([k,l])=>`<div><span>${l}</span><b>${fmt(f[k])} <small>g</small></b></div>`).join('')}</div>${f.reviewRequired?'<div class="notice warning"><p>The recorded calories and macros need review. Original estimates are retained.</p></div>':''}${f.note?`<h4>Notes</h4><p class="help preserve">${esc(f.note)}</p>`:''}${f.source?`<details class="disclosure"><summary>Nutrition source ${icon('plus')}</summary><p class="help">${esc(f.source)}</p></details>`:''}<div class="form-actions">${button('Edit','food-edit','edit','btn',`data-id="${esc(f.id)}"`)}${button('Log again','food-repeat','plus','btn secondary',`data-id="${esc(f.id)}"`)}</div>`);}
function foodForm(existing=null,template=null){
  const date=state.date,original=existing?structuredClone(existing):null,f=existing||template||{},entryId=existing?.id||id();
  openSheet(existing?'Edit food':'Log food',`<form><div class="form-date">${icon('calendar')} ${dateLabel(date,{weekday:'short',day:'numeric',month:'long'})}${template?tag('REPEAT PORTION'):''}</div><label class="field">Food or drink<input name="name" required maxlength="160" value="${esc(f.name)}" placeholder="What did you have?"></label><label class="field">Portion<input name="quantity" required maxlength="160" value="${esc(f.quantity)}" placeholder="e.g. 200 g cooked, or 1 scoop (30 g)"></label><div class="form-grid">${[['kcal','Calories (kcal)'],['protein','Protein (g)'],['carbs','Carbs (g)'],['fat','Fat (g)']].map(([k,l])=>numberField(k,l,f[k],{placeholder:'Unknown'})).join('')}</div><label class="checkbox-label"><input type="checkbox" name="estimated" ${f.estimated!==false?'checked':''}>Nutrition is an estimate</label><label class="field">Notes / label details<textarea name="note" maxlength="5000" rows="3">${esc(f.note)}</textarea></label><p class="help">Repeating a food copies its saved portion and nutrition. Review both when changing the serving size.</p>${existing?button('Delete this entry','food-delete','close','textbtn danger-text',`data-id="${esc(existing.id)}"`):''}${saveFooter()}</form>`,()=>wireForm(async fd=>{
    const entry={...f,id:entryId,name:fd.get('name').trim(),quantity:fd.get('quantity').trim(),estimated:fd.has('estimated'),note:fd.get('note').trim(),source:f.source||'Manually entered in Cam’s Health',loggedAt:original?.loggedAt||new Date().toISOString()};delete entry.date;
    for(const k of ['kcal','protein','carbs','fat'])entry[k]=fd.get(k)===''?null:Number(fd.get(k));
    if(!entry.name||!entry.quantity)throw Error('Enter a food name and portion.');
    entry.reviewRequired=entry.kcal!=null&&[entry.protein,entry.carbs,entry.fat].every(v=>v!=null)&&Math.abs(entry.kcal-(4*entry.protein+4*entry.carbs+9*entry.fat))>Math.max(25,entry.kcal*.1);
    await store.save(data=>upsert(ensureDay(data,date).food,entry,original),`${original?'Correct':'Log'} food for ${date}`);
  }));
}
function upsert(entries,entry,baseline){const index=entries.findIndex(e=>e.id===entry.id);if(index>=0&&JSON.stringify(entries[index])===JSON.stringify(entry))return;if(baseline){if(index<0)throw Error('This entry was removed elsewhere.');assertUnchanged(entries[index],baseline);entries[index]=entry;}else if(index<0)entries.push(entry);else throw Error('An entry with this ID already exists. Refresh and review it before retrying.');}
function recipeForm(recipeId){const recipe=store.data.recipes.find(r=>r.id===recipeId),date=state.date,entryId=id();if(!recipe)return;const per=recipe.per100g||recipe.per100Grams;if(!per)return toast('This recipe is missing its portion nutrition.');openSheet('Recipe portion',`<form><span class="eyebrow">SAVED RECIPE</span><h3>${esc(recipe.name)}</h3><p class="help">${fmt(recipe.yieldG)} g cooked batch. Nutrition scales from the saved per-100 g estimate.</p><label class="field">Your portion (grams)<input name="grams" id="recipe-grams" type="number" inputmode="decimal" required min="1" max="10000" step="any" placeholder="e.g. 200"></label><div id="recipe-preview" class="recipe-preview">Enter your portion to preview its nutrition.</div><p class="help preserve">${esc(recipe.note||recipe.notes)}</p>${saveFooter('Log portion')}</form>`,()=>{
    $('#recipe-grams',sheet).addEventListener('input',e=>{const g=Number(e.target.value);$('#recipe-preview',sheet).innerHTML=g>0?`<b>${per.kcal==null?'Unknown':fmt(round(per.kcal*g/100))} kcal</b><span>${per.protein==null?'Unknown':fmt(round(per.protein*g/100))} g protein · portion estimate</span>`:'Enter your portion to preview its nutrition.';});
    wireForm(async fd=>{const g=Number(fd.get('grams')),entry={id:entryId,recipeId,portionGrams:g,name:recipe.name,quantity:`${g} g cooked portion`,estimated:true,source:'Saved recipe '+recipeId,note:recipe.note||'',loggedAt:new Date().toISOString()};for(const k of ['kcal','protein','carbs','fat'])entry[k]=per[k]==null?null:round(per[k]*g/100);await store.save(data=>upsert(ensureDay(data,date).food,entry,null),`Log recipe portion for ${date}`);});
  });}
function recordDetails(recordId,date=state.date){const w=dayFor(store.data,date).workouts.find(w=>w.id===recordId);if(!w)return;openSheet('Your session',`<span class="eyebrow">${dateLabel(date,{weekday:'long',day:'numeric',month:'long'})}</span><h3 class="sheet-hero-title">${esc(w.name)}</h3><div class="workout-detail-stats">${tag(w.status==='completed'?'Completed':'Partial')}${tag(w.durationMin==null?'Duration not logged':fmt(w.durationMin)+' minutes')}${actualSets(w)?tag(actualSets(w)+' reported sets'):''}</div>${w.actualExercises?.length?`<div class="table-scroll"><table><thead><tr><th>Actual exercise</th><th>Sets</th><th>Reps</th><th>kg</th></tr></thead><tbody>${w.actualExercises.map(e=>`<tr><td>${esc(e.name)}</td><td>${fmt(e.sets)}</td><td>${esc(e.reps??'–')}</td><td>${fmt(e.load??e.loadKg)}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="help preserve">${esc(w.notes||'No performance notes recorded.')}</p><div class="form-actions">${button('Edit session','workout-edit','edit','btn',`data-id="${esc(w.id)}" data-for-date="${date}"`)}${w.sessionId?button('See prescription','open-workout','arrow','btn secondary',`data-id="${esc(w.sessionId)}"`):''}</div>`);}
function exerciseRow(e={}){return `<div class="exercise-input"><label class="field exercise-name">Exercise<input name="exerciseName" value="${esc(e.name)}" maxlength="160" placeholder="e.g. Lateral raise"></label>${numberField('exerciseSets','Sets',e.sets,{max:100,step:1,placeholder:'–'})}<label class="field">Reps<input name="exerciseReps" value="${esc(e.reps)}" maxlength="50" placeholder="12, 11, 10"></label>${numberField('exerciseLoad','Load (kg)',e.load??e.loadKg,{max:1000,placeholder:'–'})}<button type="button" class="iconbtn remove-exercise" aria-label="Remove exercise">${icon('close')}</button></div>`;}
function workoutForm(existing=null,date=state.date,sessionId=null){
 const original=existing?structuredClone(existing):null,w=existing||{},entryId=w.id||id(),selected=original?(w.sessionId||'custom'):(sessionId||'custom');
 openSheet(existing?'Edit session':'Log a session',`<form><div class="form-date">${icon('calendar')}${dateLabel(date,{weekday:'long',day:'numeric',month:'long'})}</div><label class="field">Session<select name="sessionId" id="session-select"><option value="custom" ${selected==='custom'?'selected':''}>Custom session</option>${store.data.training.sessions.map(s=>`<option value="${esc(s.id)}" ${selected===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label class="field" id="custom-name">Session name<input name="name" maxlength="160" value="${esc(w.sessionId==null?w.name:'')}" placeholder="e.g. Back + Shoulders"></label><div class="form-grid">${numberField('durationMin','Duration (minutes)',w.durationMin,{min:1,max:1440,step:1,placeholder:'Unknown'})}<label class="field">Completion status<select name="status" required><option value="" ${!w.status&&selected!=='rest'?'selected':''}>Choose status</option><option value="completed" ${w.status==='completed'||selected==='rest'?'selected':''}>Completed</option><option value="partial" ${w.status==='partial'?'selected':''}>Partial / still in progress</option></select></label></div><details class="measurement-fields" ${w.actualExercises?.length?'open':''}><summary>${icon('train')}Actual exercises <span>Optional</span>${icon('plus')}</summary><p class="help">Only enter work you actually did. Reps can be a list (12, 11, 10). Loads are recorded in kilograms.</p><div id="exercise-inputs">${(w.actualExercises||[]).map(exerciseRow).join('')}</div>${button('Add exercise','add-exercise','plus','btn secondary')}</details><label class="field">Session notes<textarea name="notes" rows="3" maxlength="5000" placeholder="How it felt, substitutions, any pain">${esc(w.notes)}</textarea></label>${existing?button('Delete this session','workout-delete','close','textbtn danger-text',`data-id="${esc(w.id)}" data-for-date="${date}"`):''}${saveFooter('Save session')}</form>`,()=>{
 const select=$('#session-select',sheet),toggle=()=>{$('#custom-name',sheet).hidden=select.value!=='custom';};toggle();select.addEventListener('change',toggle);
 wireForm(async fd=>{const sid=fd.get('sessionId'),s=store.data.training.sessions.find(s=>s.id===sid),exercises=$$('.exercise-input',sheet).map(row=>({name:$('[name=exerciseName]',row).value.trim(),sets:$('[name=exerciseSets]',row).value===''?null:Number($('[name=exerciseSets]',row).value),reps:$('[name=exerciseReps]',row).value.trim()||null,load:$('[name=exerciseLoad]',row).value===''?null:Number($('[name=exerciseLoad]',row).value)})).filter(e=>e.name||e.sets!=null||e.reps||e.load!=null);if(exercises.some(e=>!e.name))throw Error('Name each actual exercise, or remove the empty row.');const entry={...w,id:entryId,sessionId:sid==='custom'?null:sid,name:s?.name||fd.get('name').trim(),status:fd.get('status'),durationMin:fd.get('durationMin')===''?null:Number(fd.get('durationMin')),notes:fd.get('notes').trim(),actualExercises:exercises,loggedAt:w.loggedAt||new Date().toISOString()};if(!entry.name)throw Error('Give this custom session a name.');await store.save(data=>upsert(ensureDay(data,date).workouts,entry,original),`Log training for ${date}`);});
 });
}
function metricForm(type){const d=dayFor(store.data,state.date),date=state.date,config={steps:['steps','Daily steps','Total steps for this date',200000],water:['waterMl','Water intake','Total water (ml)',20000],notes:['notes','Day notes','Your notes',0]}[type];const [key,title,label,max]=config,baseline=d[key];openSheet(title,`<form><div class="form-date">${icon('calendar')}${dateLabel(date,{weekday:'long',day:'numeric',month:'long'})}</div>${type==='notes'?`<label class="field">${label}<textarea name="value" rows="5" maxlength="5000">${esc(baseline)}</textarea></label>`:numberField('value',label,baseline,{max,step:1,placeholder:'Not logged'})}<p class="help">${type==='notes'?'Saved with this date.':'This replaces the daily total. It does not add to the previous number. Leave blank to clear it.'}</p>${saveFooter()}</form>`,()=>wireForm(async fd=>{const value=type==='notes'?fd.get('value'):fd.get('value')===''?null:Number(fd.get('value'));await store.save(data=>{const d=ensureDay(data,date);assertUnchanged(d[key],baseline);d[key]=value;},`Update ${type} for ${date}`);}));}
function deleteForm(kind,entry,date){openSheet('Delete this record?',`<form><h3>${esc(entry.name)}</h3><p class="help">This removes the ${kind==='food'?'food entry':'session'} for ${dateLabel(date)}. Its older versions remain in GitHub’s commit history. Other records are preserved.</p>${saveFooter('Confirm delete')}</form>`,()=>wireForm(async()=>{await store.save(data=>{const list=ensureDay(data,date)[kind],current=list.find(e=>e.id===entry.id);if(current)assertUnchanged(current,entry);ensureDay(data,date)[kind]=list.filter(e=>e.id!==entry.id);},`Delete ${kind} record for ${date}`);}));}
function connectForm(){
 openSheet('Connect GitHub',`<div class="connect-intro"><span class="item-icon large">${icon('github')}</span><h3>${store.connected?'This tab is authorized.':'Your repo. Your control.'}</h3><p>Read-only access is automatic. To save directly from your phone, authorize this browser separately from ChatGPT.</p></div>${store.connected?`<div class="notice soft">${icon('check')}<p>Signed in as <b>${esc(store.account)}</b>. Token held in memory only. Contents write access is checked on your first save.</p></div>${button('Disconnect this tab','disconnect','lock','btn secondary full')}`:`<form id="connect-form"><div class="connection-steps"><div><b>01</b><p>Create a fine-grained token. Select <strong>only Cam-s-Health</strong> under repository access.</p></div><div><b>02</b><p>Grant <strong>Contents: Read and write</strong>. No other write permissions are needed for tracking.</p></div><div><b>03</b><p>Paste the token below. Do not send it in a chat message.</p></div></div><a class="btn secondary full" href="${TOKEN_URL}" target="_blank" rel="noopener noreferrer">Open GitHub token setup ${icon('arrow')}</a><label class="field">GitHub token<input name="token" type="password" required autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Paste securely into this field"></label><p class="help">The token is sent only to api.github.com. It is never stored in browser storage, source code, exports, or health.json. Closing this tab disconnects it.</p><p id="form-error" class="form-error" role="alert"></p><button class="btn full" type="submit">${icon('github')}Authorize this tab</button></form>`}<p class="help privacy-copy">Your GitHub repository is public. Connecting does not make its food or measurement records private.</p>`,()=>{
 const form=$('#connect-form',sheet);if(!form)return;form.addEventListener('submit',async e=>{e.preventDefault();const input=$('[name=token]',form),button=$('[type=submit]',form);button.disabled=true;try{await store.connect(input.value);input.value='';dirty=false;closeSheet(true);toast('GitHub token accepted. This tab can attempt saves.');}catch(e){$('#form-error',form).textContent=e.message;}finally{button.disabled=false;}});
 });
}
function targetsForm(){const baseline=structuredClone(store.data.profile),targets=baseline.targets,height=fromMetric(baseline.heightCm,'heightCm',state.units),displayHeight=height==null?'':String(Math.round(height*100)/100);openSheet('Targets & profile',`<form><p class="help">These are your chosen tracking targets, not an estimate of maintenance calories. Blank leaves a target unset.</p><div class="form-grid">${[['kcal','Daily calories (kcal)'],['protein','Protein (g)'],['carbs','Carbs (g)'],['fat','Fat (g)'],['steps','Steps']].map(([k,l])=>numberField(k,l,targets[k],{min:k==='kcal'?1:0,placeholder:'No target',step:k==='steps'?1:'any'})).join('')}${numberField('heightCm','Height ('+unit('heightCm')+')',displayHeight,{min:.1,max:fromMetric(300,'heightCm',state.units)})}</div><label class="field">Training status<select name="trainingStatus">${[['awaiting clearance','Awaiting exercise clearance'],['paused','Training paused'],['ready','Ready / cleared to train']].map(([v,l])=>`<option value="${v}" ${baseline.trainingStatus===v?'selected':''}>${l}</option>`).join('')}</select><small>Only select ready when you have confirmed you can resume training. Logged sessions do not establish medical clearance.</small></label>${saveFooter('Save preferences')}</form>`,()=>wireForm(async fd=>{const target={};for(const k of ['kcal','protein','carbs','fat','steps'])target[k]=fd.get(k)===''?null:Number(fd.get(k));const h=String(fd.get('heightCm'))===displayHeight?baseline.heightCm??null:fd.get('heightCm')===''?null:toMetric(Number(fd.get('heightCm')),'heightCm',state.units);await store.save(data=>{assertUnchanged(data.profile.targets,baseline.targets);assertUnchanged(data.profile.heightCm,baseline.heightCm);assertUnchanged(data.profile.trainingStatus,baseline.trainingStatus);data.profile.targets=target;data.profile.heightCm=h;data.profile.trainingStatus=fd.get('trainingStatus');if(data.profile.trainingStatus!==baseline.trainingStatus)data.profile.trainingNote='Training status explicitly updated by the user in app settings.';},'Update targets and profile');}));}
function quickLog(){openSheet('What are we logging?',`<p class="help">For ${dateLabel(state.date,{weekday:'long',day:'numeric',month:'long'})}.</p><div class="quick-grid">${[['Food or drink','food-log','food','Calories & macros'],['Body check-in','body-log','body','Weight, fat & measurements'],['Workout','workout-log','train','Your actual session'],['Steps','steps','steps','Daily total'],['Water','water','water','Daily total'],['Day notes','notes','edit','Keep the context']].map(([l,a,i,s])=>`<button class="quick-choice" data-act="${a}"><span class="item-icon">${icon(i)}</span><b>${l}</b><small>${s}</small></button>`).join('')}</div>`);}
function syncInfo(){openSheet('Sync diagnostics',`<div class="notice ${store.error?'warning':'soft'}">${icon(store.error?'info':'check')}<div><b>${esc(store.status)}</b><p>${store.error?esc(store.error):'The last accepted file passed the entry-ID and body-measurement validators.'}</p></div></div><dl class="diagnostics"><dt>Repository</dt><dd>${REPO}</dd><dt>Record</dt><dd>dist/data/health.json · main</dd><dt>Data timestamp</dt><dd>${esc(store.data?.updatedAt||'Unknown')}</dd><dt>Last successful read</dt><dd>${esc(store.checkedAt||'Not verified')}</dd><dt>Browser authorization</dt><dd>${store.connected?'Token accepted; writes verified on save':'Read only. Chat uses a separate connection.'}</dd><dt>Last verified browser save</dt><dd>${store.lastCommit?esc(store.lastCommit.slice(0,12)):'No save in this tab'}</dd></dl><p class="help">Public reads try GitHub raw content first and the API second. Invalid records are rejected with a precise error. Cached data is explicitly marked as not live.</p><div class="form-actions">${button('Refresh','refresh-sheet','refresh')}${button('Connection','connect','github','btn secondary')}</div>`);}
function briefSheet(){openSheet('Your daily brief',`<pre class="brief-text">${esc(brief(store.data,state.date))}</pre><div class="form-actions">${button('Copy brief','copy-brief','copy')}${button('Print','print','download','btn secondary')}</div>`);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied.');}catch{openSheet('Copy your brief',`<textarea readonly class="copy-area">${esc(text)}</textarea>`);$('.copy-area',sheet).select();}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportBody(){const columns=['Date','Weight kg','Body fat %','Method',...BODY_FIELDS.map(([,l])=>l+' cm')],rows=bodyDays(store.data,state.date).reverse().map(([date,d])=>[date,d.weightKg??'',d.body?.bodyFatPct??'',d.body?.method??'',...BODY_FIELDS.map(([k])=>d.body?.measurementsCm?.[k]??'')]);const csv=[columns,...rows].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');download(`cams-body-${state.date}.csv`,'\uFEFF'+csv,'text/csv;charset=utf-8');toast('Body history exported.');}
function startTimer(seconds){state.timerEnd=Date.now()+seconds*1000;state.timerPaused=0;persist('timer',String(state.timerEnd));updateTimer();toast(`${seconds}s rest timer started.`);}
function remaining(){return state.timerEnd?Math.max(0,Math.ceil((state.timerEnd-Date.now())/1000)):state.timerPaused;}
function timerClock(n){return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
function timerSheet(){openSheet('Rest timer',`<div class="timer-face"><span class="eyebrow">BETWEEN SETS</span><strong id="timer-display">${timerClock(remaining())}</strong><p>A timer, not a workout duration log.</p></div><div class="timer-presets">${[60,90,120,180].map(s=>`<button data-seconds="${s}" class="btn secondary">${s}s</button>`).join('')}</div><div class="form-actions">${button('Pause / resume','timer-pause','timer','btn secondary')}${button('+30 seconds','timer-add','plus','btn secondary')}${button('Reset','timer-reset','close','textbtn')}</div><p class="help">The timer uses the clock when you switch tabs. Your browser may delay the alert while the app is in the background.</p>`);updateTimer();}
function updateTimer(){const dock=$('#timer-dock'),left=remaining(),active=state.timerEnd||state.timerPaused;dock.hidden=!active;if(active){dock.innerHTML=`<button data-act="timer">${icon('timer')}<b>${timerClock(left)}</b><span>${state.timerEnd?'Rest timer':'Paused'}</span></button>${iconButton('Stop rest timer','timer-reset','close')}`;const display=$('#timer-display');if(display)display.textContent=timerClock(left);}if(state.timerEnd&&left===0){state.timerEnd=0;persist('timer','0');dock.hidden=true;const display=$('#timer-display');if(display)display.textContent='0:00';toast('Rest timer finished.');if(document.visibilityState==='visible')navigator.vibrate?.(150);}}
setInterval(updateTimer,500);
function readRoute(){const url=new URL(location.href),date=url.searchParams.get('date');if(validDate(date))state.date=date;const parts=url.hash.slice(1).split('/');state.detail=null;if(parts[0]==='workout'&&parts[1]){state.view='training';try{state.detail=decodeURIComponent(parts[1]);}catch{state.detail=null;}}else state.view=['dashboard','nutrition','training','body','settings','history'].includes(parts[0])?parts[0]:'dashboard';}
function navigate(view,detail=null){if(sheet.open){dirty=false;closingFromHistory=true;sheet.close();closingFromHistory=false;history.replaceState({sheet:false},'');}state.view=view;state.detail=detail;const url=new URL(location.href);url.searchParams.set('date',state.date);url.hash=detail?'workout/'+encodeURIComponent(detail):view;history.pushState({sheet:false},'',url);render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function selectDate(date,view=state.view){if(!validDate(date))return;state.date=date;state.view=view;state.detail=null;const url=new URL(location.href);url.searchParams.set('date',date);url.hash=view;history.replaceState({sheet:false},'',url);render();}
window.addEventListener('popstate',()=>{if(sheet.open&&!history.state?.sheet){if(dirty){history.pushState({...history.state,sheet:true},'');closeSheet();}else{closingFromHistory=true;closeSheet(true);closingFromHistory=false;}return;}readRoute();render();});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
let heldTimers=[];
function attachHolds(){heldTimers.forEach(clearTimeout);heldTimers=[];$$('[data-workout]',root).forEach(el=>{let timer,start;const clear=()=>clearTimeout(timer);el.addEventListener('pointerdown',e=>{if(e.button!==0)return;start=[e.clientX,e.clientY];timer=setTimeout(()=>{if(!el.isConnected)return;el.dataset.held='1';previewWorkout(el.dataset.workout);},450);heldTimers.push(timer);});el.addEventListener('pointermove',e=>{if(start&&Math.hypot(e.clientX-start[0],e.clientY-start[1])>10)clear();});['pointerup','pointercancel','pointerleave'].forEach(type=>el.addEventListener(type,clear));el.addEventListener('contextmenu',e=>e.preventDefault());});}
function previewWorkout(sid){const s=store.data.training.sessions.find(s=>s.id===sid);if(s)openSheet('Workout preview',`<span class="eyebrow">PRESCRIBED, NOT COMPLETED</span><h3 class="sheet-hero-title">${esc(s.name)}</h3><p class="help">${esc(s.focus)}</p>${exerciseList(s)}${button('Open full workout','open-workout','arrow','btn full',`data-id="${esc(s.id)}"`)}`);}
async function action(act,b){
 if(act==='close-sheet')return closeSheet();if(act==='discard'){dirty=false;return closeSheet(true);}if(act==='keep-editing'){$('.discard-confirm',sheet).hidden=true;return;}
 if(act==='quick')return quickLog();if(act==='body-log')return bodyForm();if(act==='food-log')return foodForm();if(act==='workout-log')return workoutForm(null,state.date,b?.dataset.session||state.detail);
 if(['steps','water','notes'].includes(act))return metricForm(act);
 if(act==='theme'){state.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';persist('theme',state.theme);applyTheme();if(!sheet.open)render();return;}
 if(act==='refresh')return store.load();if(act==='refresh-sheet'){closeSheet(true);return store.load();}
 if(act==='today')return selectDate(today(store.data.profile.timezone));if(act==='prev'||act==='next')return selectDate(shiftDate(state.date,act==='prev'?-1:1));
 if(['training','body','history'].includes(act))return navigate(act);if(act==='food-page')return navigate('nutrition');
 if(act==='open-workout')return navigate('training',b.dataset.id);
 if(act==='connect')return connectForm();if(act==='disconnect'){store.disconnect();closeSheet(true);toast('Disconnected. Read-only access remains available.');return;}
 if(act==='sync-info')return syncInfo();if(act==='targets')return targetsForm();if(act==='brief')return briefSheet();if(act==='copy-brief')return copyText(brief(store.data,state.date));
 if(act==='print'){closeSheet(true);navigate('dashboard');setTimeout(()=>window.print(),150);return;}
 if(act==='export')return download(`cams-health-${state.date}.json`,JSON.stringify(store.data,null,2),'application/json');if(act==='body-export')return exportBody();
 if(act==='food-edit'||act==='food-repeat'||act==='food-delete'){const f=dayFor(store.data,state.date).food.find(f=>f.id===b.dataset.id);if(!f)return;if(act==='food-edit')return foodForm(f);if(act==='food-repeat')return foodForm(null,f);return deleteForm('food',f,state.date);}
 if(act==='workout-edit'||act==='workout-delete'){const date=b.dataset.forDate,w=dayFor(store.data,date).workouts.find(w=>w.id===b.dataset.id);if(!w)return;return act==='workout-edit'?workoutForm(w,date):deleteForm('workouts',w,date);}
 if(act==='add-exercise'){$('#exercise-inputs',sheet).insertAdjacentHTML('beforeend',exerciseRow());dirty=true;return;}
 if(act==='timer')return timerSheet();if(act==='timer-reset'){state.timerEnd=0;state.timerPaused=0;persist('timer','0');$('#timer-display')?.replaceChildren('0:00');updateTimer();return;}
 if(act==='timer-add')return startTimer(remaining()+30);if(act==='timer-pause'){const left=remaining();if(state.timerEnd){state.timerPaused=left;state.timerEnd=0;persist('timer','0');}else if(left)startTimer(left);updateTimer();}
}
document.addEventListener('click',async e=>{
 if(e.target.closest('[data-home]')){e.preventDefault();navigate('dashboard');return;}
 const b=e.target.closest('button');if(!b)return;
 try {
 if(b.dataset.held==='1'){b.dataset.held='';e.preventDefault();return;}
 if(b.matches('.remove-exercise')){b.closest('.exercise-input').remove();dirty=true;return;}
 if(b.dataset.act){e.preventDefault();return await action(b.dataset.act,b);}
 if(b.dataset.view)return navigate(b.dataset.view);
 if(b.dataset.date)return selectDate(b.dataset.date,'dashboard');
 if(b.dataset.food)return foodDetails(b.dataset.food);
 if(b.dataset.workout)return navigate('training',b.dataset.workout);
 if(b.dataset.preview)return previewWorkout(b.dataset.preview);
 if(b.dataset.record)return recordDetails(b.dataset.record,b.dataset.recordDate);
 if(b.dataset.repeat){const f=dayFor(store.data,b.dataset.origin).food.find(f=>f.id===b.dataset.repeat);return foodForm(null,f);}
 if(b.dataset.recipe)return recipeForm(b.dataset.recipe);
 if(b.dataset.bodyDate)return bodyForm(b.dataset.bodyDate);
 if(b.dataset.metric){state.metric=b.dataset.metric;if(state.view!=='body')navigate('body');else render();return;}
 if(b.dataset.range){state.range=b.dataset.range==='all'?'all':Number(b.dataset.range);render();return;}
 if(b.dataset.theme){state.theme=b.dataset.theme;persist('theme',state.theme);applyTheme();render();return;}
 if(b.dataset.units){state.units=b.dataset.units;persist('units',state.units);render();return;}
 if(b.dataset.seconds){e.preventDefault();startTimer(Number(b.dataset.seconds));}
 } catch(error){toast(error.message);}
});
document.addEventListener('change',e=>{if(e.target.id==='view-date')selectDate(e.target.value);if(e.target.id==='metric-select'){state.metric=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='food-search'){const q=e.target.value.trim().toLowerCase();let count=0;$$('.food-row').forEach(row=>{row.hidden=!row.dataset.name.includes(q);if(!row.hidden)count++;});$('#search-empty').hidden=count>0;}});
function foregroundRefresh(){if(!sheet.open&&document.visibilityState==='visible')store.load();}
window.addEventListener('online',foregroundRefresh);document.addEventListener('visibilitychange',foregroundRefresh);setInterval(foregroundRefresh,300000);
readRoute();history.replaceState({sheet:false},'');render();store.load();
